	allegiance = "Horde",
	aliases = { "Felgur" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Felgur Twocuts wurde zum {link:ghost-walker-post}Geistwandlerposten{/link} geschickt, um alles über die {link:centaurs}Zentauren{/link} in Erfahrung zu bringen, was er konnte. {link:regthar-deathgate}Regthar Deathgate{/link} schickt ihm Kämpfer aus dem {link:the-barrens}Brachland{/link}, und Felgur sagt ihnen offen, dass der Kampf lang sein wird. Er glaubt, dass die Klans gebrochen werden müssen, bevor sie je lernen, gemeinsam zu stehen.]=],
