		},
		{
			title = "Taten",
			text = [=[• Er fordert den Tod von {link:khan-dez-hepah}Khan Dez'hepah{/link} von den {link:kolkar-village}Kolkar{/link}.
• Er zahlt ein Kopfgeld auf {link:centaurs}Zentauren{/link} jedes Klans, um sie ausbluten zu lassen und sie Furcht zu lehren.]=],
		},
	},
	mentions = {
		{
			text = [=[Die {link:kolkar-village}Kolkar{/link} von {link:desolace}Desolace{/link}, von {link:regthar-deathgate}Regthar{/link}]=],
		},
		{ text = "{link:khan-dez-hepah}Khan Dez'hepah{/link}" },
		{ text = "Zentaurenkopfgeld" },
	},
	bonds = {
		{ id = "regthar-deathgate", name = "Regthar Deathgate", note = "schickt ihm Kämpfer" },
		{ id = "khan-dez-hepah", name = "Khan Dez'hepah", note = "sein Ziel" },
		{ id = "gurda-wildmane", name = "Gurda Wildmane", note = "teilt seinen Posten" },
	},
})

Translate("deDE", "gurda-wildmane", {
	title = "Gurda Wildmane",
	subtitle = "Gesandte zu den Klans",
	found = "Geistwandlerposten",
	hint = [=[Sprecht mit der Taurin am Geistwandlerposten, die ein Bündnis unter den Zentauren sucht.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gurda Wildmane ist eine Taurin des Geistwandlerpostens, die weiß, dass die {link:centaurs}Zentauren{/link} nicht allein mit Gewalt zu besiegen sind. Ihr Plan ist es, ihren Hass gegen sie selbst zu wenden. Die {link:horde}Horde{/link} wird sich mit einem Klan anfreunden, seine Geheimnisse erfahren und durch ihn lernen, wie man sie alle besiegt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Für die {link:tauren}Tauren{/link} sind die {link:centaurs}Zentauren{/link} die ältesten Feinde. Gurdas Bereitschaft, mit einem Klan gegen einen anderen zu verhandeln, zeigt, wie weit die {link:horde}Horde{/link} gehen wird, um diesen langen Krieg zu beenden.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie bietet eine Wahl an Verbündeten: die {link:magram-village}Magram{/link}, indem man {link:gelkis-village}Gelkis{/link} tötet, oder die Gelkis, indem man Magram tötet.]=],
		},
	},
	mentions = {
		{ text = "Bündnis mit den {link:magram-village}Magram{/link}" },
		{ text = "Bündnis mit den {link:gelkis-village}Gelkis{/link}" },
	},
	bonds = {
		{ id = "warug", name = "Warug", note = "der Sprecher der Magram" },
		{ id = "uthek-the-wise", name = "Uthek die Weise", note = "die Schamanin der Gelkis" },
		{ id = "felgur-twocuts", name = "Felgur Twocuts", note = "teilt ihren Posten" },
	},
})

Translate("deDE", "nataka-longhorn", {
	title = "Nataka Longhorn",
	subtitle = "Taure des Geistwandlerpostens",
	found = "Geistwandlerposten",
	hint = [=[Sprecht mit dem Tauren am Geistwandlerposten, der auf Nachricht von seinem Bruder wartet.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nataka Longhorn versieht seinen Dienst am {link:ghost-walker-post}Geistwandlerposten{/link}, fern von seiner Sippe. Sein Bruder, {link:cliffwatcher-longhorn}Klippenwächter Longhorn{/link}, wacht über den {link:freewind-post}Freiwindposten{/link} in {link:thousand-needles}Tausend Nadeln{/link}, und zwischen den Briefen seines Bruders verging ein Jahr. Als endlich Nachricht kam, sprach sie von seltsamen Regungen unter den {link:centaurs}Zentauren{/link} dort. Nataka hat auch eine schlichtere Sehnsucht: den gebratenen Blutbauchfisch aus {link:shadowprey-village}Shadowprey{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Nataka erinnert daran, dass die Zentaurenplage nicht allein {link:desolace}Desolace{/link} betrifft. Vom {link:the-barrens}Brachland{/link} bis nach {link:thousand-needles}Tausend Nadeln{/link} sind die Klans in Bewegung.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erhält den Bericht seines Bruders über ungewöhnliche Umtriebe der {link:centaurs}Zentauren{/link}.
• Er schickt zu den Trollen von {link:shadowprey-village}Shadowprey{/link} nach Fisch, denn der Krieg lässt ihm keine Zeit, selbst zu gehen.]=],
		},
	},
	mentions = {
		{ text = "Stammbaum" },
		{ text = "Der Fang des Tages" },
	},
	bonds = {
		{ id = "cliffwatcher-longhorn", name = "Klippenwächter Longhorn", note = "sein Bruder" },
	},
})

Translate("deDE", "taiga-wisemane", {
	title = "Taiga Wisemane",
	subtitle = "Älteste von Shadowprey",
	found = "Shadowprey",
	hint = [=[Sprecht mit der Taurenältesten in Shadowprey, die gegen die Flut der Dämonen kämpft.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Taiga Wisemane ist eine Taurin von hohem Alter und großer Macht, die in {link:shadowprey-village}Shadowprey{/link} lebt. Sie hat erfahren, wie die {link:burning-blade}Brennende Klinge{/link} die Dämonenportale von {link:mannoroc-coven}Mannorocs Koven{/link} öffnet: mit der Hand von Iruxos, einem grausigen Relikt, das in einer Dämonenkiste in der {link:thunder-axe-fortress}Festung Thunder Axe{/link} aufbewahrt wird. Sie will es gegen sie wenden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Wo andere die Dämonen einen nach dem anderen bekämpfen, schlägt Taiga gegen die Tür, durch die sie kommen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie schickt Krieger aus, um den roten Kristall der {link:thunder-axe-fortress}Festung Thunder Axe{/link} zu zerschlagen und die Dämonenkiste zu holen.
• Sie öffnet die Kiste und übergibt die Hand von Iruxos denen, die die Portale bannen werden.]=],
		},
	},
	mentions = {
		{ text = "Die Hand von Iruxos" },
		{ text = "Portale der Legion" },
	},
	bonds = {
		{ id = "jugkar-grim-rod", name = "Jugkar Grim'rod", note = "hält die Portale offen, die sie schließen will" },
	},
})

Translate("deDE", "drulzegar-skraghook", {
	title = "Drulzegar Skraghook",
	subtitle = "Fischer von Shadowprey",
	found = "Shadowprey",
	hint = [=[Sprecht mit dem lahmen Fischer von Shadowprey, der seine Mannschaft an die Naga verlor.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Drulzegar Skraghook fischte einst mit voller Mannschaft in den Gewässern nahe der Insel Ranazjar. Eines Morgens erhoben sich die {link:naga}Naga{/link} aus dem Riff und töteten alle außer ihm. Er kehrte mit einem kaputten Knie und einem Herzen voller Schuld heim. Er kann sie nicht selbst bekämpfen, also bezahlt er andere dafür.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Drulzegars Kummer zeigt den Preis, den die Westküste für die {link:naga}Naga{/link} zahlt. Selbst Rache füllt die Leere nicht, die sie hinterließen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bezahlt für den Tod der {link:naga}Naga{/link} der Slitherblade, die seine Mannschaft töteten.]=],
		},
	},
	mentions = {
		{ text = "Andere Fische braten" },
	},
})

Translate("deDE", "kreldig-ungor", {
	title = "Kreldig Ungor",
	subtitle = "Agent der Reclaimers Inc.",
	found = "Die Nijelspitze",
	hint = [=[Sprecht mit dem Zwerg an der Nijelspitze, der findet, was andere verloren haben.]=],
	allegiance = "Reclaimers Inc. · Königreich Ironforge",
	aliases = { "Kreldig" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kreldig Ungor ist ein {link:dwarves}Zwerg{/link} der Reclaimers Inc., eines Unternehmens aus {link:ironforge}Ironforge{/link}, das verlorene Dinge für jene findet, die zahlen können. Man hat ihn mit mehr Arbeit als Händen nach {link:desolace}Desolace{/link} geschickt, und er macht kein Geheimnis daraus, wie wenig ihm der Ort gefällt, oder das Lager. Seine Auftraggeber sind weit fort: ein Magier aus {link:stormwind-city}Stormwind{/link}, der eine Truhe an Meeresriesen verlor, und ein {link:gnomes}Gnom{/link} aus {link:dun-morogh}Dun Morogh{/link}, der die seltsamsten Reagenzien verlangt, von denen ein Zwerg je gehört hat.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Durch Kreldigs Aufträge kommen die Gefahren von {link:desolace}Desolace{/link} eine nach der anderen ans Licht: die {link:naga}Naga{/link} der Küste, die {link:satyrs}Satyrn{/link} des Nordostens und Dämonen, von denen er nie wusste, dass sie da waren.]=],
		},
		{
