Translate("deDE", "vahlarriel-demonslayer", {
	title = "Vahlarriel Demonslayer",
	subtitle = "Agentin von Darnassus",
	found = "Die Nijelspitze",
	hint = [=[Sprecht mit der Nachtelfe an der Nijelspitze, die nach zwei vermissten Adligen sucht.]=],
	allegiance = "Darnassus · Allianz",
	aliases = { "Vahlarriel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Vahlarriel Demonslayer ist eine Nachtelfe, die aus {link:darnassus}Darnassus{/link} geschickt wurde, um zwei verschollene Kinder des Hauses Malem zu finden, einer Händlerfamilie, deren Vater das Schlimmste befürchtet. Die Geschwister {link:tyranis-malem}Tyranis{/link} und {link:dalinda-malem}Dalinda{/link} zogen einige Wochen zuvor durch das {link:stonetalon-mountains}Steinkrallengebirge{/link} und verschwanden in {link:desolace}Desolace{/link}. Vahlarriels Befehle tragen einen zweiten, leiseren Zweck. Ihren Vorgesetzten liegt vor allem an Dalinda. Tyranis soll beurteilt werden, bevor man ihn heimbringt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Vahlarriels Suche enthüllt, wie weit die {link:burning-blade}Brennende Klinge{/link} reicht und wie selbst ein Kind der {link:night-elves}Nachtelfen{/link} zu der Magie hingezogen werden kann, die ihr Volk verbietet.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie bittet um Nachricht über den Wagen der Malems im Norden von {link:desolace}Desolace{/link}.
• Sie folgt den Spuren nach Süden zur {link:thunder-axe-fortress}Festung Thunder Axe{/link}.
• Sie berichtet ihren Vorgesetzten in {link:darnassus}Darnassus{/link} von jeder Wendung der Suche.]=],
		},
	},
	chapters = {
		{
			title = "Der leere Wagen",
			hint = "Findet den Wagen des Hauses Malem im Norden von Desolace.",
			text = [=[Der Wagen wurde zerschlagen aufgefunden. Zauber und Klingen hatten ihn getroffen, der Kampf war kurz gewesen, und nirgends in der Nähe lagen Leichen. Daneben lagen ein Anhänger und Spuren, die nach Süden zum Rauch einer großen Festung führten. Vahlarriel kannte den Ort vom Hörensagen. Es war der Unterschlupf von {link:orcs}Orcs{/link}, die sich Dämonen hingegeben hatten.]=],
		},
		{
			title = "Das Schicksal der Malems",
			hint = [=[Bringt Dalinda Malem sicher aus der Festung Thunder Axe heraus.]=],
			text = [=[{link:dalinda-malem}Dalinda{/link} kehrte auf eigenen Füßen zur Nijelspitze zurück, und Vahlarriel betrachtete das als Gnade. {link:tyranis-malem}Tyranis{/link} kehrte nicht zurück. Er hatte die Gunst der Kultisten gesucht, die ihn verschleppt hatten, und er starb unter ihnen. Die Schande seiner Entscheidungen würde mit seiner Schwester heimreisen, und sie allein würde sie vor ihrem Volk tragen müssen.]=],
		},
	},
	mentions = {
		{ text = "Vahlarriels Suche" },
		{ text = "Vahlarriels Suche, der Anhänger und die Spuren" },
		{ text = "Vahlarriels Suche, die Festung" },
		{ text = "Rückkehr zu Vahlarriel" },
	},
	bonds = {
		{ id = "dalinda-malem", name = "Dalinda Malem", note = "die Adlige, die sie suchte" },
		{ id = "tyranis-malem", name = "Tyranis Malem", note = "der Adlige, den sie beurteilen sollte" },
		{ id = "kreldig-ungor", name = "Kreldig Ungor", note = "teilt das Lager" },
	},
})

Translate("deDE", "dalinda-malem", {
	title = "Dalinda Malem",
	subtitle = "Tochter des Hauses Malem",
	found = "Ein Gefängnis in der Festung Thunder Axe",
	hint = [=[Sucht die nachtelfische Adlige, die von der Brennenden Klinge gefangen gehalten wird.]=],
	allegiance = "Haus Malem · Darnassus",
	aliases = { "Dalinda" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dalinda Malem ist eine Tochter eines darnassischen Händlerhauses. Sie kam gegen ihr eigenes Urteil nach {link:desolace}Desolace{/link}, weil sie ihrem Bruder folgte. Die {link:orcs}Orcs{/link} der {link:burning-blade}Brennenden Klinge{/link} töteten ihre Wachen und Diener und verschleppten sie in die {link:thunder-axe-fortress}Festung Thunder Axe{/link}, wo sie fürchtete, ihren dämonischen Herren übergeben zu werden. Sie wollte nicht fliehen, ehe sie das Schicksal ihres Bruders kannte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Dalindas Geschichte handelt von der Treue zu einem Bruder, der sie nicht verdiente. Sie vergab der Hand, die ihn tötete, wenn auch nicht gern.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie überlebte die Gefangenschaft in der {link:thunder-axe-fortress}Festung Thunder Axe{/link}.
• Sie floh zur Nijelspitze, sobald das Schicksal ihres Bruders bekannt war.]=],
		},
	},
	mentions = {
		{ text = "Vahlarriels Suche" },
		{ text = "Die Suche nach {link:tyranis-malem}Tyranis{/link}" },
		{ text = "Rückkehr zu {link:vahlarriel-demonslayer}Vahlarriel{/link}" },
	},
	bonds = {
		{ id = "tyranis-malem", name = "Tyranis Malem", note = "ihr Bruder" },
		{ id = "vahlarriel-demonslayer", name = "Vahlarriel Demonslayer", note = "wurde geschickt, um sie zu finden" },
	},
})

Translate("deDE", "tyranis-malem", {
	title = "Tyranis Malem",
	subtitle = "Der verlorene Sohn des Hauses Malem",
	found = "Festung Thunder Axe",
	hint = [=[Findet den nachtelfischen Adligen, der einen Platz unter der Brennenden Klinge suchte.]=],
	allegiance = "Brennende Klinge",
	aliases = { "Tyranis" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tyranis Malem ist der Sohn eines darnassischen Händlerhauses. Er hatte in letzter Zeit begonnen, nach allem Wissen über das Arkane zu gieren, obwohl sein Volk es verbietet, und er kam trotz aller Warnungen nach {link:desolace}Desolace{/link}. Als die {link:burning-blade}Brennende Klinge{/link} ihn gefangen nahm, versuchte er, sie mit seinem Wissen zu beeindrucken. Er wollte nicht gerettet werden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tyranis ist eine Warnung, dass der alte Hunger nach Magie, der die {link:night-elves}Nachtelfen{/link} einst ins Verderben stürzte, unter ihnen nicht erloschen ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte seine Schwester auf der Suche nach verbotenem Wissen nach {link:desolace}Desolace{/link}.
• Er bot sein Wissen den Kultisten an, die seine Diener erschlagen hatten.]=],
		},
	},
	mentions = {
		{ text = "Die Suche nach Tyranis" },
	},
	bonds = {
		{ id = "dalinda-malem", name = "Dalinda Malem", note = "seine Schwester" },
	},
})

Translate("deDE", "captain-pentigast", {
	title = "Hauptmann Pentigast",
	subtitle = "Befehlshaber der Nijelspitze",
	found = "Die Nijelspitze",
	hint = [=[Sprecht mit dem Hauptmann, der die Soldaten der Nijelspitze befehligt.]=],
	allegiance = "Allianz",
	aliases = { "Pentigast" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hauptmann Pentigast befehligt die Soldaten der Allianz an der Nijelspitze. Er beobachtet die Kriege der {link:centaurs}Zentauren{/link} mit kaltem Blick. Er glaubt, dass der Klan, der siegt, aus {link:desolace}Desolace{/link} hervorbrechen und die Festungen der {link:alliance}Allianz{/link} bedrohen wird, und er hat nicht vor, das geschehen zu lassen. Seine Antwort ist Politik: sich auf eine Seite schlagen, das Vertrauen eines Klans gewinnen und lernen, wie man sie alle schlägt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Pentigast bringt die {link:alliance}Allianz{/link} in dasselbe Spiel, das die {link:horde}Horde{/link} am {link:ghost-walker-post}Geistwandlerposten{/link} spielt. Beide Seiten werben nun um die Klans, mit dem Blut anderer {link:centaurs}Zentauren{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt Gesandte zu {link:uthek-the-wise}Uthek{/link} der Weisen von den {link:gelkis-village}Gelkis{/link} oder zu {link:warug}Warug{/link} von den {link:magram-village}Magram{/link}.]=],
		},
	},
	mentions = {
		{ text = "Ein seltsames Bündnis" },
		{ text = "Brutale Politik" },
	},
	bonds = {
		{ id = "uthek-the-wise", name = "Uthek die Weise", note = "eine mögliche Verbündete" },
		{ id = "warug", name = "Warug", note = "ein möglicher Verbündeter" },
		{ id = "corporal-melkins", name = "Korporal Melkins", note = "dient unter ihm" },
	},
})

Translate("deDE", "corporal-melkins", {
	title = "Korporal Melkins",
	subtitle = "Soldat der Nijelspitze",
	found = "Die Nijelspitze",
	hint = [=[Sprecht mit dem Korporal der Nijelspitze, der Zentaurenohren zählt.]=],
	allegiance = "Allianz",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Korporal Melkins dient an der Nijelspitze. Er ist der Ansicht, dass jeder Zentaurenklan, welchen Khan oder welches Ziel er auch haben mag, einen Wesenszug teilt, und dieser Wesenszug ist Grausamkeit. Frieden wird seiner Meinung nach erst kommen, wenn die {link:centaurs}Zentauren{/link} fort sind. Bis dahin bezahlt er für ihre Ohren.]=],
