Translate("deDE", "brother-anton", {
	title = "Bruder Anton",
	subtitle = "Abgesandter des Scharlachroten Kreuzzugs",
	found = "Die Nijelspitze",
	hint = [=[Sprecht mit dem Bruder in Rot, der von jenseits des Meeres zur Nijelspitze gekommen ist.]=],
	allegiance = "Scharlachroter Kreuzzug",
	aliases = { "Anton" },
	sections = {
