	},
})

Translate("deDE", "keeper-marandis", {
	title = "Bewahrer Marandis",
	subtitle = "Bewahrer des Zirkels des Cenarius",
	found = "Die Nijelspitze",
	hint = [=[Sprecht mit dem Bewahrer an der Nijelspitze, der wegen Maraudon gekommen ist.]=],
	allegiance = "Zirkel des Cenarius",
	aliases = { "Marandis" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bewahrer Marandis kam um {red:maraudon}Maraudon{/red}s willen nach {link:desolace}Desolace{/link}. Er erzählt allen, die zuhören, von Prinzessin Theradras, einer Macht der elementaren Erde, auf irgendeine Weise den Alten Göttern verwandt, die von Zaetar aufgesucht wurde, dem ersten Sohn des {link:cenarius}Cenarius{/link}. Die {link:centaurs}Zentauren{/link} waren ihre Kinder, und die Zentauren töteten ihren Vater. Nun bewahrt Theradras seine Überreste, und der Bewahrer will, dass sie heimgebracht werden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Marandis trägt den Kummer des {link:cenarion-circle}Zirkels des Cenarius{/link}. Zaetar war der Bruder von {link:keeper-remulos}Remulos{/link}, und die Druiden haben ihn nie vergessen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bittet um Champions, die stark genug sind, Theradras zu erschlagen und die Überreste Zaetars zurückzuholen.
• {link:selendra}Selendra{/link}, die dasselbe Werk am Ende des Landes verrichtet, das der {link:horde}Horde{/link} gehört, sucht seinen Rat.]=],
		},
	},
	mentions = {
		{ text = "Die Verderbnis von Erde und Saat" },
	},
	bonds = {
		{ id = "selendra", name = "Selendra", note = "teilt seine Sache" },
		{ id = "talendria", name = "Talendria", note = "Druidin wie er an der Nijelspitze" },
	},
})

Translate("deDE", "selendra", {
	title = "Selendra",
	subtitle = "Druidin des Zirkels des Cenarius",
	found = "Ein Druidenlager nahe Shadowprey",
	hint = "Sprecht mit der Druidin, die südlich von Shadowprey lagert.",
	allegiance = "Zirkel des Cenarius",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Selendra ist eine Druidin des {link:cenarion-circle}Zirkels des Cenarius{/link}, die nahe {link:shadowprey-village}Shadowprey{/link} wartet. Wie {link:keeper-marandis}Bewahrer Marandis{/link} sucht sie die Überreste Zaetars, und wie er muss sie die sterblichen Völker um Hilfe bitten. Lieber würde sie die Schlacht selbst schlagen. Sie sagt, dass Zaetar, der Bruder von {link:keeper-remulos}Remulos{/link}, viel Leid in die Welt brachte und dass es mit seinem Tod endete, und sie hofft, dass ihre Bitte nicht noch mehr verursacht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Selendra zeigt, wie der Zirkel zwischen der {link:alliance}Allianz{/link} und der {link:horde}Horde{/link} steht und beide um dieselbe Hilfe bittet.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie bittet darum, Prinzessin Theradras zu erschlagen, damit die Überreste Zaetars ins {link:stonetalon-mountains}Steinkrallengebirge{/link} zurückgebracht werden können.]=],
		},
	},
	mentions = {
		{ text = "Die Verderbnis von Erde und Saat" },
	},
	bonds = {
		{ id = "keeper-marandis", name = "Bewahrer Marandis", note = "teilt ihre Sache" },
	},
})

Translate("deDE", "talendria", {
	title = "Talendria",
	subtitle = "Druidin der Nijelspitze",
	found = "Die Nijelspitze",
	hint = [=[Sprecht mit der Nachtelfe an der Nijelspitze, die die verderbten Pflanzen von Maraudon erforscht.]=],
	allegiance = "Allianz",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Talendria erforscht die Verderbnis in {red:maraudon}Maraudon{/red}. Ein {link:satyrs}Satyr{/link} namens Vyletongue hat seine Höhlen vergiftet und das Wachstum jeder Pflanze darin verkümmern lassen. Sie hat eine Phiole angefertigt, deren Beschichtung das verderbte Wasser in ein Heilmittel verwandelt, und sie hofft, dass die Pflanzen von Maraudon noch geheilt werden können, auch wenn Vyletongue sie weiterhin in seiner Gewalt hat.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Wo andere das Böse in Maraudon erschlagen wollen, will Talendria heilen, was es verletzt hat.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie gibt eine Phiole aus, um die verderbten Teiche zu reinigen und die Vylestem-Ranken zu heilen.]=],
		},
	},
	mentions = {
		{ text = "Die Verderbnis von Vyletongue" },
	},
	bonds = {
		{ id = "keeper-marandis", name = "Bewahrer Marandis", note = "Druide wie sie an der Nijelspitze" },
		{ id = "vark-battlescar", name = "Vark Battlescar", note = "verrichtet dasselbe Werk für die Horde" },
	},
})

Translate("deDE", "vark-battlescar", {
	title = "Vark Battlescar",
	subtitle = "Aus Shadowprey",
	found = "Shadowprey",
	hint = [=[Sprecht mit jenem in Shadowprey, der die Pflanzen von Maraudon heilen will.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Vark Battlescar aus {link:shadowprey-village}Shadowprey{/link} hat dieselbe Arbeit auf sich genommen wie {link:talendria}Talendria{/link} von der Nijelspitze. Auch er weiß, dass der {link:satyrs}Satyr{/link} Vyletongue die Höhlen von {red:maraudon}Maraudon{/red} verderbt hat, und auch er bietet eine Phiole an, um ihr Gift in ein Heilmittel zu verwandeln. Dass die {link:horde}Horde{/link} und die {link:alliance}Allianz{/link} dieselbe Krankheit von gegenüberliegenden Ufern aus erforschen, ist ein kleines Zeichen dafür, wie viel das Grab bedeutet.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Vark zeigt, dass die Sorge um die lebenden Dinge Maraudons nicht das Werk eines einzigen Volkes ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Er gibt eine Phiole aus, um den orangefarbenen Kristallteich zu reinigen und die Vylestem-Ranken zu heilen.]=],
		},
	},
	mentions = {
		{ text = "Die Verderbnis von Vyletongue" },
	},
	bonds = {
		{ id = "talendria", name = "Talendria", note = "verrichtet dasselbe Werk für die Allianz" },
	},
})

Translate("deDE", "cavindra", {
	title = "Cavindra",
	subtitle = "Schwester von Celebras",
	found = "Nahe dem Eingang von Maraudon",
	hint = [=[Sucht die Frau nahe den Toren von Maraudon, die um ihren Bruder trauert.]=],
	allegiance = "Sippe von Celebras",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Cavindra wartet nahe den Toren von {red:maraudon}Maraudon{/red} und erwacht aus etwas, das sie einen Albtraum nennt, der kein Ende zu haben schien. Ihr Bruder Celebras irrt blind im Inneren umher, verflucht von der Verderbnis. Der {link:satyrs}Satyr{/link} Lord Vyletongue und ein lebendiges Sinnbild seiner Verderbnis namens Noxxion haben die beiden Hälften des Zepters ihres Bruders gestohlen. Sie will, dass die Stücke gefunden werden und dass man ihren Bruder erreicht, wie auch immer das gelingen mag.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Cavindras Kummer ist für Außenstehende das erste Zeichen, dass mehr als {link:centaurs}Zentauren{/link} im Grab Zaetars hausen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie erzählt von Vyletongue und Noxxion und von dem gestohlenen Zepter des Celebras.]=],
		},
	},
	mentions = {
		{ text = "Legenden von Maraudon" },
	},
	bonds = {
		{ id = "celebras-the-cursed", name = "Celebras der Verfluchte", note = "ihr Bruder" },
	},
})

Translate("deDE", "centaur-pariah", {
	title = "Zentaurenpariah",
	subtitle = "Verbannter der Klans",
	found = "Unterwegs im Süden von Desolace",
	hint = [=[Sucht den verstoßenen Zentauren, der allein durch die südlichen Hügel zieht.]=],
	allegiance = "Keine, von den Klans verstoßen",
	aliases = { "der Pariah" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Zentaurenpariah wurde von seinem Volk als Ketzer verstoßen. Er glaubt noch immer, was ihm die Verbannung einbrachte: dass die Klans zu einem großen Stamm geschmiedet werden können. Um dieses Werk zu beginnen, braucht er einen Außenstehenden, jemanden ohne Klan, der bereit ist, die heiligen Hallen von {red:maraudon}Maraudon{/red} zu betreten, in die nur die frömmsten {link:centaurs}Zentauren{/link} eintreten dürfen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[In einem Land, in dem die Klans leben, um einander zu töten, ist der Pariah der einzige {link:centaurs}Zentaur{/link}, der von ihrer Einigung träumt. Dieser Traum ist vielleicht das Gefährlichste in {link:desolace}Desolace{/link}, denn jedes andere Volk hofft, dass die Klans sich niemals vereinen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er gibt schriftliche Anweisungen an jene, die bereit sind, für ihn Maraudon zu betreten.
• Er will das große Werk beginnen, die Stämme zu einen.]=],
		},
	},
	chapters = {
		{
			title = "Ein großer Stamm",
			hint = "Tut in den Hallen von Maraudon, worum der Pariah bittet.",
			text = [=[Der Außenstehende ging in das Grab und kam mit dem zurück, was der Pariah brauchte. Er frohlockte. Nun, sagte er, könne das große Werk beginnen. Er entlohnte seinen Helfer und hoffte, dass sie sich beim nächsten Mal unter ganz anderen Umständen begegnen würden. Noch kann niemand sagen, welche Umstände das sein werden.]=],
		},
	},
	mentions = {
		{ text = "Die Anleitung des Pariahs" },
	},
	bonds = {
		{ id = "uthek-the-wise", name = "Uthek die Weise", note = "aus einem Klan, den er vereinen will" },
		{ id = "warug", name = "Warug", note = "aus einem Klan, den er vereinen will" },
	},
})

Translate("deDE", "uthek-the-wise", {
	title = "Uthek die Weise",
	subtitle = "Schamanin der Gelkis",
	found = "Am Rand von Gelkis",
	hint = [=[Sucht die Schamanin der Gelkis, die das Flüstern der Erde hört.]=],
	allegiance = "Gelkisklan",
	aliases = { "Uthek" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Uthek die Weise ist eine Schamanin des Gelkisklans, und sie spricht für ihr Volk zu den wenigen Fremden, die es duldet. Sie lauscht der Erde, und die Erde antwortet ihr: Sie sagt ihr, wann die {link:magram-village}Magram{/link} schwach werden, wo ein ferner Kristall liegt und wessen Hände nass vom Blut der Magram sind. Sie glaubt, dass Erdmagie stärker ist als die Macht jedes Kriegers und dass die {link:gelkis-village}Gelkis{/link} eines Tages über {link:desolace}Desolace{/link} herrschen werden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Uthek ist die Stimme des Glaubens der {link:centaurs}Zentauren{/link} an Theradras. Durch sie nehmen die {link:gelkis-village}Gelkis{/link} die Hilfe von {link:alliance}Allianz{/link} und {link:horde}Horde{/link} gleichermaßen an, und durch sie werden diese Fremden in einen Klankrieg hineingezogen, der älter ist als ihre eigenen Nationen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie prüft Fremde an den {link:magram-village}Magram{/link}, die sie erschlagen haben.
• Sie schickt sie aus, um die Fleischvorräte der Magram zu plündern und den Stolz der {link:kolkar-village}Kolkar{/link} zu brechen.
• Sie giert nach Draenethyst, einem roten Kristall, der neu in der Erde Azeroths ist und der, wie sie sagt, aus einem Land stammt, in dem Berge fliegen und Dämonen herrschen.
• Sie fordert den Tod von {link:khan-jehn}Khan Jehn{/link} von den Magram und von {link:khan-hratha}Khan Hratha{/link} von den Maraudine.]=],
		},
	},
	chapters = {
		{
			title = "Eine Freundin der Gelkis",
			hint = "Gewinnt das Vertrauen der Schamanin der Gelkis.",
			text = [=[Uthek grüßt keine Fremden. Sie wartet, bis die Erde ihr sagt, dass sie viele {link:magram-village}Magram{/link} getötet haben, und dann spricht sie. Ihre ersten Worte sind ein Angebot: Sie sollen ihr sagen, was sie für die {link:gelkis-village}Gelkis{/link} tun können, und sie wird ihnen sagen, was die Gelkis für sie tun können.]=],
		},
		{
			title = "Die Scherbe des Verirrten",
			hint = [=[Bringt der Schamanin den roten Kristall, den sie in der Erde hört.]=],
			text = [=[Die Erde flüsterte Uthek von einem Kristall namens Draenethyst, den ein Verirrter namens {link:ongeku}Ongeku{/link} in den {link:swamp-of-sorrows}Sümpfen des Elends{/link} besaß. Als die Scherbe in ihre Hände gelegt wurde, spürte sie sofort ihre Macht, und sie schwor, sie gegen die Feinde ihres Klans zu wenden.]=],
		},
		{
			title = "Der Fall der Khane",
			hint = "Streckt die Khane nieder, die die Schamanin nennt.",
			text = [=[{link:khan-jehn}Khan Jehn{/link} sei stark und töricht, sagte Uthek, denn er sehe nicht, dass die Magie der Erde stärker sei als sein Arm. Als er fiel, nannte sie als Nächstes den Khan der Maraudine. {link:khan-hratha}Hratha{/link} trug das Bruchstück eines Schlüssels, und sie wollte es haben. Als auch er tot war, versprach sie, dass die Geister der Erde den Namen dessen besingen würden, der ihn erschlagen hatte.]=],
		},
	},
	mentions = {
		{ text = "Bündnis mit den {link:gelkis-village}Gelkis{/link}" },
		{ text = "Ein seltsames Bündnis" },
		{ text = "Überfall auf die {link:kolkar-village}Kolkar{/link}" },
		{ text = "Vorräte stehlen" },
		{ text = "{link:ongeku}Ongeku{/link}" },
		{ text = "{link:khan-jehn}Khan Jehn{/link}" },
		{ text = "{link:khan-hratha}Khan Hratha{/link}" },
	},
	bonds = {
		{ id = "khan-shaka", name = "Khan Shaka", note = "ihr Khan" },
		{ id = "warug", name = "Warug", note = "der Feind ihres Klans" },
		{ id = "khan-jehn", name = "Khan Jehn", note = "sie trachtete nach seinem Kopf" },
		{ id = "khan-hratha", name = "Khan Hratha", note = "sie trachtete nach seinem Kopf" },
	},
})

Translate("deDE", "warug", {
	title = "Warug",
	subtitle = "Sprecher der Magram",
	found = "Am Rand von Magram",
	hint = [=[Sucht den Magram, der am Rand ihres Dorfes für seinen Klan spricht.]=],
	allegiance = "Magramklan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Warug spricht für die {link:magram-village}Magram{/link} zu den wenigen Fremden, die sich das Recht verdienen, ihn zu hören. Er ist laut, grausam und stolz. Die Magram brauchen keinen Schutz, sagt er, nicht von Theradras und nicht von irgendwem, denn sie sind die Stärksten. Er lacht, wenn er tötet, und er heißt andere, dasselbe zu tun, damit ihre Feinde sehen, wie schwach sie sind.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Warug ist das Glaubensbekenntnis der {link:magram-village}Magram{/link} in Fleisch und Blut: Stärke vor Glauben und Gelächter über den Toten. Er ist auch der Beweis, dass die Magram trotz all ihrer Verachtung Hilfe von Fremden annehmen, wenn es ihnen nützt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er prüft Fremde an den {link:gelkis-village}Gelkis{/link}, die sie erschlagen haben.
• Er schickt sie aus, um die Tränen der Theradras zu zerschlagen, die die Gelkis horten.
• Er fordert den Tod von {link:khan-shaka}Khan Shaka{/link} von den Gelkis und {link:khan-hratha}Khan Hratha{/link} von den Maraudine.
• Er tötete einst einen gnomischen Händler, der nach {link:desolace}Desolace{/link} kam, behielt aber ein Spielzeug aus dem Karren des Gnoms, weil es ihn zum Lachen brachte.]=],
		},
	},
	chapters = {
		{
			title = "Ein Freund der Magram",
			hint = "Gewinnt den Respekt des Sprechers der Magram.",
			text = [=[Die {link:magram-village}Magram{/link} sprechen nicht mit den Schwachen. Sie töten sie. Warug sagte nichts, bis die {link:gelkis-village}Gelkis{/link} beim Namen eines Fremden weinten. Dann räumte er ein, dass der Fremde vielleicht stark sei wie die Magram und dass die Magram und der Fremde vielleicht Freunde sein könnten.]=],
		},
		{
			title = "Die Tränen der Theradras",
			hint = "Zerbrecht, wovon die Gelkis glauben, dass es sie beschützt.",
			text = [=[In einer Höhle in ihrem Dorf bewahrten die {link:gelkis-village}Gelkis{/link} Kristalle auf, die sie die Tränen der Theradras nannten. Warug wollte sie zerschlagen und die Stücke zu sich gebracht sehen. Wenn die Tränen zerbrächen, sagte er, würden die Gelkis lernen, dass ihre Mutter ihnen nicht helfen und nicht einmal weinen würde, wenn die {link:magram-village}Magram{/link} sie zermalmten.]=],
		},
		{
			title = "Der Kopf von Shaka",
			hint = "Streckt die Khane nieder, die Warug nennt.",
			text = [=[Als {link:khan-shaka}Khan Shaka{/link} fiel, steckte Warug seinen Kopf auf eine Pike und behielt ihn in seiner Nähe, damit Shaka zusehen konnte, wie die {link:magram-village}Magram{/link} stark wurden. Als Nächstes schickte er seine Freunde gegen {link:khan-hratha}Hratha{/link} von den Maraudine. Als auch dieser Khan starb, versprach Warug, dass sein Helfer von den Hufen der Magram verschont bliebe, wenn alle anderen niedergetrampelt würden.]=],
		},
	},
	mentions = {
		{ text = "Bündnis mit den {link:magram-village}Magram{/link}" },
		{ text = "Brutale Politik" },
		{ text = "Angriff auf die {link:kolkar-village}Kolkar{/link}" },
		{ text = "Zerbrochene Tränen" },
		{ text = "Ein Apparat für Warug" },
		{ text = "{link:khan-shaka}Khan Shaka{/link}" },
		{ text = "{link:khan-hratha}Khan Hratha{/link}" },
	},
	bonds = {
		{ id = "khan-jehn", name = "Khan Jehn", note = "sein Khan" },
		{ id = "uthek-the-wise", name = "Uthek die Weise", note = "die Feindin seines Klans" },
		{ id = "khan-shaka", name = "Khan Shaka", note = "er trachtete nach seinem Kopf" },
		{ id = "khan-hratha", name = "Khan Hratha", note = "er trachtete nach seinem Kopf" },
	},
})

