	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lord Azrethoc ist ein Dämonenfürst, der in {link:mannoroc-coven}Mannorocs Koven{/link} haust. Seine Unterschrift wurde auf einem Vertrag gefunden, der in einer alten dämonischen Sprache auf zerrissene Haut geschrieben war. Er band Kultisten der {link:burning-blade}Brennenden Klinge{/link} an seinen Dienst. Als {link:maurin-bonesplitter}Maurin Bonesplitter{/link} sein Bild beschwor, war selbst die Erscheinung stärker als der Hexenmeister, der sie rief.]=],
