		},
		{
			title = "Taten",
			text = [=[• Er schloss Pakte mit der Brennenden Klinge von {link:desolace}Desolace{/link}.
• Ihm dient der orcische Hexenmeister {link:jugkar-grim-rod}Jugkar Grim'rod{/link}.]=],
		},
	},
	mentions = {
