Translate("deDE", "azore-aldamort", {
	title = "Azore Aldamort",
	subtitle = "Magier der Argentumdämmerung",
	found = "Ein Hügel über Ethel Rethor",
	hint = [=[Sucht den Magier, der von den Hügeln von Ethel Rethor aus die Naga und die Brennende Klinge beobachtet.]=],
	allegiance = "Argentumdämmerung",
	aliases = { "Aldamort" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Azore Aldamort ist ein Magier, der von den Hügeln von {link:ethel-rethor}Ethel Rethor{/link} aus Wache hält. Er hat erfahren, dass die {link:burning-blade}Brennende Klinge{/link} den {link:naga}Naga{/link} ein Relikt namens Zepter des Lichts abgenommen hat, das der Legende nach ganze Städte im Meer versinken lassen kann. Er ist entschlossen, dass die Kultisten es nicht behalten sollen. Er sucht auch die eigenen Geheimnisse der Naga, die seit Jahrhunderten in einem Buch der Ahnen verwahrt werden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Aldamort wacht über Relikte, die für jede Hand zu gefährlich sind, und vor allem für die Hände derer, die Dämonen dienen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sucht das Zepter des Lichts beim Seher der Brennenden Klinge in der {link:thunder-axe-fortress}Festung Thunder Axe{/link}.
• Er schickt den Edelstein der Schlange zur Insel Ranazjar, um den Hüter des Buches der Ahnen herbeizurufen, und gibt das Buch an einen hohen Rat weiter.]=],
		},
	},
