	allegiance = "Goblinhändler",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hornizz Brimbuzzle unterhält ein Lager neben dem Kodofriedhof, zusammen mit seiner Schwester Melizza, die ständig in Schwierigkeiten gerät. Einmal ging sie ins Tal der Speere, um mit den Maraudine zu handeln, und landete beinahe in deren Kochtopf. Hornizz hat einen eigenen, kühneren Plan. Mit einer Kiste voller Geistermagnete will er die Essenz der Magramgeister im {link:valley-of-bones}Tal der Knochen{/link} einfangen und sie an die {link:magram-village}Magram{/link} zurückverkaufen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Hornizz ist der Goblingeist in seiner schamlosesten Form: Kein Handel ist zu seltsam, wenn vielleicht jemand dafür bezahlt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bezahlt für die Rettung seiner Schwester vor den Maraudine.
• Er sammelt Geisteressenz im {link:valley-of-bones}Tal der Knochen{/link}.]=],
		},
	},
	mentions = {
		{ text = "Holt mich hier raus!, Melizzas Rettung" },
		{ text = "Geistoplasma-Treibjagd" },
	},
})
